import os
from typing import Any, Dict, Optional

import requests

OPENAI_API_KEY_ENV = "OPENAI_API_KEY"
OPENAI_VISION_MODEL = "gpt-4.1-mini"
OPENAI_API_URL = "https://api.openai.com/v1/responses"


def check_image_for_unsafe_content(image_url: Optional[str] = None, image_bytes: Optional[bytes] = None) -> Dict[str, Any]:
    if not image_url and not image_bytes:
        raise ValueError("Provide either image_url or image_bytes.")

    api_key = os.getenv(OPENAI_API_KEY_ENV)
    if not api_key:
        raise EnvironmentError(f"Missing required environment variable: {OPENAI_API_KEY_ENV}")

    content = [
        {
            "type": "input_text",
            "text": (
                "Analyze this image for unsafe or policy-sensitive visual content. "
                "Return a concise JSON object with keys: "
                "unsafe (boolean), categories (array of strings), summary (string), "
                "confidence (string: low/medium/high)."
            ),
        }
    ]

    if image_url:
        content.append(
            {
                "type": "input_image",
                "image_url": image_url,
            }
        )
    else:
        import base64

        b64 = base64.b64encode(image_bytes).decode("utf-8")
        content.append(
            {
                "type": "input_image",
                "image_url": f"data:image/jpeg;base64,{b64}",
            }
        )

    payload = {
        "model": OPENAI_VISION_MODEL,
        "input": [
            {
                "role": "user",
                "content": content,
            }
        ],
        "text": {
            "format": {
                "type": "json_object"
            }
        },
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    resp = requests.post(OPENAI_API_URL, headers=headers, json=payload, timeout=60)
    resp.raise_for_status()
    data = resp.json()

    result_text = None
    for item in data.get("output", []):
        for c in item.get("content", []):
            if c.get("type") in {"output_text", "text"}:
                result_text = c.get("text")
                break
        if result_text:
            break

    if not result_text:
        return {
            "unsafe": False,
            "categories": [],
            "summary": "No structured output returned from the API.",
            "confidence": "low",
            "raw": data,
        }

    import json

    try:
        parsed = json.loads(result_text)
        if isinstance(parsed, dict):
            return parsed
    except json.JSONDecodeError:
        pass

    return {
        "unsafe": False,
        "categories": [],
        "summary": result_text,
        "confidence": "low",
        "raw": data,
    }
